const normalize = function transportIntake({ body }) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Transport request must be a JSON object.');
  const text = (value) => value == null ? '' : String(value).trim();
  const raw = text(body.weight_kg).replace(/\s/g, '').replace(',', '.');
  const weight = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw) ? Number(raw) : NaN;
  const normalized_request = { pickup_postcode: text(body.pickup_postcode), delivery_postcode: text(body.delivery_postcode), pickup_date: text(body.pickup_date), weight_kg: Number.isFinite(weight) ? weight : null };
  const missing_fields = Object.entries(normalized_request).filter(([, value]) => value === '' || value === null).map(([field]) => field);
  return { status: missing_fields.length ? 'needs_review' : 'ready', missing_fields, normalized_request };
}

return $input.all().map((item,index) => ({json: normalize({body: item.json.body ?? item.json}), pairedItem: {item:index}}));
